  /* ------------------------------------------- customer refused delivery */

  useEffect(() => {
    if (refuseResendIn <= 0) return undefined;
    const t = setTimeout(() => setRefuseResendIn((n) => n - 1), 1000);
    return () => clearTimeout(t);
  }, [refuseResendIn]);

  useEffect(() => {
    if (refuseExpiresIn <= 0) return undefined;
    const t = setTimeout(() => setRefuseExpiresIn((n) => n - 1), 1000);
    return () => clearTimeout(t);
  }, [refuseExpiresIn]);

  /** Emails a fresh refusal code to the customer on `order`. */
  const sendRefusalOtp = async (order, { resend = false } = {}) => {
    setRefuseSending(true);
    setRefuseError("");
    setRefuseNotice("");

    try {
      const res = await authFetch(`/api/orders/${order.id}/refusal-otp/send`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ reason: effectiveRefuseReason }),
      });
      const data = await res.json();

      if (!res.ok || !data.success) {
        setRefuseError(data.error || "Could not send the code. Please try again.");
        if (data.retryAfterSeconds) setRefuseResendIn(data.retryAfterSeconds);
        return false;
      }

      setRefuseSentTo(data.sentTo || "");
      setRefuseReasons(data.reasons || []);
      setRefuseResendIn(data.resendAfterSeconds || 30);
      setRefuseExpiresIn(Math.round((data.expiresInMinutes || 10) * 60));
      setRefuseOtp("");
      if (resend) setRefuseNotice("A new code has been emailed.");
      return true;
    } catch (err) {
      console.error("Refusal code send failed:", err);
      setRefuseError("Network error. Check your connection and try again.");
      return false;
    } finally {
      setRefuseSending(false);
    }
  };

  // "Other" is not a reason, it is a prompt for one — so what gets saved is
  // the typed text, never the literal word.
  const REFUSE_OTHER = "Other";

  // The dropdown is now shown before anything is sent, so the presets have to
  // be known up front rather than arriving in the send response. The server
  // accepts any non-empty reason up to 200 characters, so this list is a
  // convenience for the agent, not a constraint it has to match.
  const REFUSE_PRESETS = [
    "Customer refused the order",
    "Customer not available",
    "Wrong or incomplete address",
    "Customer unable to pay",
    "Item damaged on arrival",
  ];
  const refusePresetList = refuseReasons.length ? refuseReasons : REFUSE_PRESETS;
  const effectiveRefuseReason =
    refuseReasonChoice === REFUSE_OTHER ? refuseCustomReason.trim() : refuseReasonChoice;

  // The dialog opens on the reason, and only moves to the code once a valid
  // one has been given: nothing is emailed to the customer before that.
  const openRefusal = (order) => {
    setOrderToRefuse(order);
    setRefuseStage("reason");
    setRefuseOtp("");
    setRefuseReasonChoice("");
    setRefuseCustomReason("");
    setRefuseError("");
    setRefuseNotice("");
    setRefuseSentTo("");
    setRefuseResendIn(0);
    setRefuseExpiresIn(0);
    // The reason list is only known once the server has been asked, so seed it
    // from the presets the last send returned; it is refreshed on send.
  };

  /**
   * Step one: validate the reason, then ask the server to email the code.
   * The dialog only moves on if the send actually succeeded.
   */
  const handleSendRefusalOtp = async (e) => {
    if (e) e.preventDefault();
    if (!orderToRefuse) return;

    if (!effectiveRefuseReason) {
      setRefuseError(
        refuseReasonChoice === REFUSE_OTHER
          ? "Type the reason for the cancellation."
          : "Choose a reason for the cancellation."
      );
      return;
    }

    const ok = await sendRefusalOtp(orderToRefuse);
    if (ok) setRefuseStage("otp");
  };

  const closeRefusal = () => {
    if (refuseSending || refuseVerifying) return;
    setOrderToRefuse(null);
    setRefuseStage("reason");
    setRefuseOtp("");
    setRefuseReasonChoice("");
    setRefuseCustomReason("");
    setRefuseError("");
    setRefuseNotice("");
  };

  // A correct code is the customer confirming at the door that they do not
  // want the order, so the backend cancels it, records the reason, and leaves
  // the payment exactly as it stands — flagging a refund if one is owed.
  const handleConfirmRefusal = async (e) => {
    if (e) e.preventDefault();
    if (!orderToRefuse) return;

    if (!/^\d{6}$/.test(refuseOtp)) {
      setRefuseError("Enter the 6-digit code from the customer.");
      return;
    }
    if (!effectiveRefuseReason) {
      setRefuseError(
        refuseReasonChoice === REFUSE_OTHER
          ? "Type the reason for the cancellation."
          : "Choose a reason for the cancellation."
      );
      return;
    }

    setRefuseVerifying(true);
    setRefuseError("");
    setRefuseNotice("");

    try {
      const res = await authFetch(`/api/orders/${orderToRefuse.id}/refusal-otp/verify`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ otp: refuseOtp, reason: effectiveRefuseReason }),
      });
      const data = await res.json();

      if (!res.ok || !data.success) {
        setRefuseError(data.error || "Incorrect code. Please try again.");
        if (data.expired) {
          setRefuseExpiresIn(0);
          setRefuseOtp("");
        }
        return;
      }

      setOrders((prev) =>
        prev.map((o) => (o.id === orderToRefuse.id ? { ...o, status: "cancelled" } : o))
      );
      if (selectedOrder && selectedOrder.id === orderToRefuse.id) {
        setSelectedOrder({ ...selectedOrder, status: "cancelled" });
      }

      setOrderToRefuse(null);
      setRefuseOtp("");
      setRefuseReasonChoice("");
    setRefuseCustomReason("");
      alert(
        data.refundDue
          ? "✅ Order cancelled. It was paid online, so a refund is due — the admin has been emailed."
          : "✅ Order cancelled. No cash was collected. Confirmation emailed to the customer."
      );
    } catch (err) {
      console.error("Refusal verification failed:", err);
      setRefuseError("Network error. Check your connection and try again.");
    } finally {
      setRefuseVerifying(false);
    }
  };

